// WatchBetBear is a free log subscription operation binding the contract event 0x0d8c1fe3e67ab767116a81f122b83c2557a8c2564019cb7c4f83de1aeb1f1f0d.
//
// Solidity: event BetBear(address indexed sender, uint256 indexed epoch, uint256 amount)
func (_Contracts *ContractsFilterer) WatchBetBear(opts *bind.WatchOpts, sink chan<- *ContractsBetBear, sender []common.Address, epoch []*big.Int) (event.Subscription, error) {

	var senderRule []interface{}
	for _, senderItem := range sender {
		senderRule = append(senderRule, senderItem)
	}
	var epochRule []interface{}
	for _, epochItem := range epoch {
		epochRule = append(epochRule, epochItem)
	}

	logs, sub, err := _Contracts.contract.WatchLogs(opts, "BetBear", senderRule, epochRule)
	if err != nil {
		return nil, err
	}
	return event.NewSubscription(func(quit <-chan struct{}) error {
		defer sub.Unsubscribe()
		for {
			select {
			case log := <-logs:
				// New log arrived, parse the event and forward to the user
				event := new(ContractsBetBear)
				if err := _Contracts.contract.UnpackLog(event, "BetBear", log); err != nil {
					return err
				}
				event.Raw = log

				select {
				case sink <- event:
				case err := <-sub.Err():
					return err
				case <-quit:
					return nil
				}
			case err := <-sub.Err():
				return err
			case <-quit:
				return nil
			}
		}
	}), nil
}

